import{_ as e,o as a,c as d,a2 as s}from"./chunks/framework.DoCD98hS.js";const k=JSON.parse('{"title":"CodePlayer · 示例一键进在线编辑器","description":"","frontmatter":{},"headers":[],"relativePath":"modules/catalog/codeplayer.md","filePath":"modules/catalog/codeplayer.md","lastUpdated":1795586119000}'),o={name:"modules/catalog/codeplayer.md"};function i(l,t,h,r,p,c){return a(),d("div",null,[...t[0]||(t[0]=[s('<h1 id="codeplayer-·-示例一键进在线编辑器" tabindex="-1">CodePlayer · 示例一键进在线编辑器 <a class="header-anchor" href="#codeplayer-·-示例一键进在线编辑器" aria-label="Permalink to &quot;CodePlayer · 示例一键进在线编辑器&quot;">​</a></h1><p>属性面板的工具栏上有个「编辑 ▾」，里面那项「在新窗口打开」会把当前示例打包成一份可直接运行的文件集，交给 CodePlayer 打开。这一篇说清楚它交给对方什么、地址从哪来、出问题先看哪里。</p><h2 id="会看到什么" tabindex="-1">会看到什么 <a class="header-anchor" href="#会看到什么" aria-label="Permalink to &quot;会看到什么&quot;">​</a></h2><p>在任一框架的组件演示页，点「编辑 ▾ → 在新窗口打开」，新标签页里是一个在线编辑器：</p><table tabindex="0"><thead><tr><th>区域</th><th>内容</th></tr></thead><tbody><tr><td>左侧文件树</td><td><code>index.html</code>、入口文件、<code>App.vue</code> 或 <code>App.tsx</code>、<code>import-map.json</code></td></tr><tr><td>中间编辑器</td><td>当前示例的用法代码，参数就是面板上的当前值</td></tr><tr><td>右侧预览</td><td>远程组件真实渲染出来的样子</td></tr></tbody></table><p>改中间代码，右侧会跟着重编译。想让示例里出现的组件能渲染，取决于下面这节。</p><h2 id="打开的是哪个站点" tabindex="-1">打开的是哪个站点 <a class="header-anchor" href="#打开的是哪个站点" aria-label="Permalink to &quot;打开的是哪个站点&quot;">​</a></h2><p>CodePlayer 是独立站点，按固定优先级取地址：</p><table tabindex="0"><thead><tr><th>优先级</th><th>来源</th><th>用途</th></tr></thead><tbody><tr><td>1</td><td>构建期注入的 <code>__HEL_CODE_PLAY_ORIGIN__</code></td><td>自托管时固定指向自己的地址</td></tr><tr><td>2</td><td>公共基址 + <code>@melt-js/website-codeplayer/</code></td><td>站点的托管目录与组件产物同源时自动拼出</td></tr><tr><td>3</td><td>官方站 <code>https://play.fe-dev.cn/</code></td><td>前两条都没有时的兜底</td></tr></tbody></table><p>想自己托管，用 <code>@melt-js/website-codeplayer</code>：这是一个源码形态的包，构建 website 外壳和 CodePlayer 内核，产物直接放进站点的静态目录即可。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">HEL_CODE_PLAY_BASE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/@melt-js/website-codeplayer/</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> vite</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre></div><p><code>HEL_CODE_PLAY_BASE</code> 决定产物内部的资源前缀，站点部署在别的前缀时改它就行。包里的发布前置校验会核对 <code>dist</code> 是否缺失、前缀是否和这次构建一致，不一致直接中止，避免发出去一份地址对不上的站点。</p><h2 id="生成代码里的地址怎么走" tabindex="-1">生成代码里的地址怎么走 <a class="header-anchor" href="#生成代码里的地址怎么走" aria-label="Permalink to &quot;生成代码里的地址怎么走&quot;">​</a></h2><p>生成的文件集不写死任何域名：</p><table tabindex="0"><thead><tr><th>资源</th><th>地址形式</th></tr></thead><tbody><tr><td>框架运行时（Vue / React 的 UMD）</td><td>站点相对路径</td></tr><tr><td>核心库（<code>@melt-js/libs-core</code> 的 CDN 产物）</td><td>站点相对路径</td></tr><tr><td>组件的 <code>hel-meta.json</code></td><td>站点相对路径，必要时追加一条公共源兜底</td></tr></tbody></table><p><code>import-map.json</code> 里的框架与远程成员走内联桥接模块，从页面全局拿到实例再按名导出。因此在预览区里，<code>from &#39;vue&#39;</code>、<code>from &#39;react&#39;</code> 和你示例里的组件名都能解析到同一份实例，不会出现两套响应式系统。</p><h2 id="让示例里的组件渲染出来" tabindex="-1">让示例里的组件渲染出来 <a class="header-anchor" href="#让示例里的组件渲染出来" aria-label="Permalink to &quot;让示例里的组件渲染出来&quot;">​</a></h2><p>远程组件默认不在编辑器里。生成时随文件集带一份依赖声明：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;comps-vue3&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;metas&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/…/hel-meta.json&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://unpkg.com/…&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] }]</span></span></code></pre></div><p>编辑器打开后按这份声明逐个加载，加载完再按名字注册成全局组件（Vue 2 用 <code>Vue.component</code>，Vue 3 用 <code>app.component</code>，React 走 <code>demo</code> 桥接的具名导入）。第一条路径拿不到就试第二条，全部失败时预览区是空的，而不是整个示例报错。</p><p>排查顺序建议：</p><ol><li>右侧空白、左侧代码正常 → 先看组件包名是否等于实际依赖的包名，再看 <code>hel-meta.json</code> 那条地址能不能直接访问。</li><li>报「组件未解析」 → 检查示例里的标签名是不是该包真实导出的成员名。</li><li>整个编辑器打不开 → 检查站点地址是否可达，以及生成时用的基址和站点实际部署前缀是否一致。</li></ol><h2 id="窄屏下的样子" tabindex="-1">窄屏下的样子 <a class="header-anchor" href="#窄屏下的样子" aria-label="Permalink to &quot;窄屏下的样子&quot;">​</a></h2><p>站点本身会按屏幕宽度调整：宽度不超过 768px 时，文件树默认收起（齿轮菜单里仍可手动打开），编辑器与预览改成上下堆叠，高度按可视区算。手机上写两行代码再看一眼效果，不需要来回切页签。</p><h2 id="相关包" tabindex="-1">相关包 <a class="header-anchor" href="#相关包" aria-label="Permalink to &quot;相关包&quot;">​</a></h2><table tabindex="0"><thead><tr><th>包名</th><th>职责</th></tr></thead><tbody><tr><td><code>@melt-js/website-codeplayer</code></td><td>CodePlayer 站点，源码形态，可自托管</td></tr><tr><td><code>@melt-js/libs-vue2-leva</code> / <code>@melt-js/libs-vue3-leva</code> / <code>@melt-js/libs-react-leva</code></td><td>属性面板与示例工具栏，提供「在新窗口打开」入口</td></tr><tr><td><code>@melt-js/libs-core</code></td><td>生成文件集、地址解析与预加载逻辑</td></tr></tbody></table>',26)])])}const b=e(o,[["render",i]]);export{k as __pageData,b as default};
